import React, { useState, useEffect } from 'react';
import { Card, Button, Alert, api } from '../App';

const UploadBox = ({ title, desc, color, onUpload, loading, result }) => {
  const [file, setFile] = useState(null);
  const [drag, setDrag] = useState(false);

  const handleFile = f => {
    if (!f) return;
    const ext = f.name.split('.').pop().toLowerCase();
    if (!['xlsx','xls','csv'].includes(ext)) { alert('Only .xlsx, .xls, .csv allowed'); return; }
    setFile(f);
  };

  return (
    <Card style={{ flex:1, border:`2px solid ${drag ? color : '#e2e8f0'}`, transition:'border 0.2s' }}>
      <div style={{ borderLeft:`4px solid ${color}`, paddingLeft:12, marginBottom:16 }}>
        <h3 style={{ fontSize:16, color:'#1a2533' }}>{title}</h3>
        <p style={{ fontSize:12, color:'#888', marginTop:2 }}>{desc}</p>
      </div>

      <div
        onDragOver={e => { e.preventDefault(); setDrag(true); }}
        onDragLeave={() => setDrag(false)}
        onDrop={e => { e.preventDefault(); setDrag(false); handleFile(e.dataTransfer.files[0]); }}
        style={{
          border:'2px dashed #cbd5e0', borderRadius:8, padding:'28px 16px',
          textAlign:'center', cursor:'pointer', background: drag?'#f0f8ff':'#fafbfc',
          marginBottom:14
        }}
        onClick={() => document.getElementById(`file-${title.replace(/\s/g,'')}`).click()}
      >
        <input
          id={`file-${title.replace(/\s/g,'')}`}
          type="file" accept=".xlsx,.xls,.csv"
          style={{ display:'none' }}
          onChange={e => handleFile(e.target.files[0])}
        />
        {file ? (
          <>
            <div style={{ fontSize:28 }}>📄</div>
            <div style={{ fontSize:13, fontWeight:600, color:'#333', marginTop:6 }}>{file.name}</div>
            <div style={{ fontSize:11, color:'#888' }}>{(file.size/1024).toFixed(1)} KB</div>
          </>
        ) : (
          <>
            <div style={{ fontSize:32, marginBottom:6 }}>📥</div>
            <div style={{ fontSize:13, color:'#666' }}>Drag & drop or <span style={{ color:color, fontWeight:600 }}>browse</span></div>
            <div style={{ fontSize:11, color:'#aaa', marginTop:4 }}>.xlsx · .xls · .csv</div>
          </>
        )}
      </div>

      {result && (
        <Alert
          msg={result.error ? `❌ ${result.error}` : `✅ Imported ${result.imported} rows · Skipped ${result.skipped}`}
          type={result.error ? 'error' : 'success'}
        />
      )}
      {result?.errors?.length > 0 && (
        <div style={{ fontSize:11, color:'#c0392b', background:'#fee2e2', padding:8, borderRadius:4, marginBottom:8 }}>
          {result.errors.slice(0,5).map((e,i) => <div key={i}>{e}</div>)}
        </div>
      )}

      <Button
        onClick={() => { if (file) onUpload(file); }}
        disabled={!file || loading}
        variant="primary"
        style={{ width:'100%', background: color }}
      >
        {loading ? 'Uploading…' : `Upload ${title}`}
      </Button>
      {file && <Button onClick={() => setFile(null)} variant="outline" size="sm" style={{ marginTop:8, width:'100%' }}>Clear</Button>}
    </Card>
  );
};

const ColumnMapper = ({ rows, type, onMapped }) => {
  if (!rows || rows.length === 0) return null;
  const cols = Object.keys(rows[0]);
  const fields = type === 'catalogue'
    ? ['garden','grade','mark','sale_no','invoice_no','bags','net_wt','broker','upset_price','last_sale_price','week_date']
    : ['garden','grade','mark','sale_no','invoice_no','bags','net_wt','broker','deal_price','buyer_code','week_date'];

  const [map, setMap] = useState({});
  const setCol = (field, col) => setMap(m => ({ ...m, [field]: col }));

  return (
    <Card>
      <h3 style={{ marginBottom:14 }}>Column Mapping Preview</h3>
      <div style={{ fontSize:12, color:'#888', marginBottom:12 }}>
        Showing first 3 rows. Auto-detection is built-in; use this to verify.
      </div>
      <div style={{ overflowX:'auto', marginBottom:16 }}>
        <table style={{ fontSize:12, borderCollapse:'collapse' }}>
          <thead>
            <tr>{cols.map(c => <th key={c} style={{ padding:'4px 8px', background:'#f0f4f8', border:'1px solid #e2e8f0' }}>{c}</th>)}</tr>
          </thead>
          <tbody>
            {rows.slice(0,3).map((r,i) => (
              <tr key={i}>{cols.map(c => <td key={c} style={{ padding:'4px 8px', border:'1px solid #e2e8f0' }}>{String(r[c] || '').slice(0,20)}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
      <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
        {fields.map(f => (
          <div key={f} style={{ minWidth:180 }}>
            <label style={{ fontSize:11, fontWeight:600, color:'#555' }}>{f}</label>
            <select
              value={map[f] || ''}
              onChange={e => setCol(f, e.target.value)}
              style={{ width:'100%', padding:'4px 6px', fontSize:12, border:'1px solid #cbd5e0', borderRadius:4 }}
            >
              <option value="">— auto detect —</option>
              {cols.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        ))}
      </div>
      <Button onClick={() => onMapped(map)} variant="success" style={{ marginTop:14 }}>
        Confirm Mapping & Import
      </Button>
    </Card>
  );
};

export default function ImportPage() {
  const [catResult,  setCatResult]  = useState(null);
  const [soldResult, setSoldResult] = useState(null);
  const [catLoading,  setCatLoading]  = useState(false);
  const [soldLoading, setSoldLoading] = useState(false);
  const [logs, setLogs] = useState([]);

  const loadLogs = () => api.get('/import/logs').then(r => setLogs(r.data)).catch(() => {});
  useEffect(() => { loadLogs(); }, []);

  const uploadCatalogue = async (file) => {
    setCatLoading(true);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const r = await api.post('/import/catalogue', fd);
      setCatResult(r.data);
      loadLogs();
    } catch (e) {
      setCatResult({ error: e.response?.data?.error || e.message });
    } finally {
      setCatLoading(false);
    }
  };

  const uploadSoldList = async (file) => {
    setSoldLoading(true);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const r = await api.post('/import/sold-list', fd);
      setSoldResult(r.data);
      loadLogs();
    } catch (e) {
      setSoldResult({ error: e.response?.data?.error || e.message });
    } finally {
      setSoldLoading(false);
    }
  };

  return (
    <div>
      <h2 style={{ marginBottom:6, color:'#1a3c5e' }}>📥 Import Excel Files</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>
        Upload the Catalogue sheet (every Thursday) and the Sold List from the auction software.
        Duplicate rows are automatically handled.
      </p>

      <div style={{ display:'flex', gap:16, marginBottom:24, flexWrap:'wrap' }}>
        <UploadBox
          title="Catalogue"
          desc="Weekly catalogue from auction house (received Thursday)"
          color="#1a3c5e"
          onUpload={uploadCatalogue}
          loading={catLoading}
          result={catResult}
        />
        <UploadBox
          title="Sold List"
          desc="Current week sold list with deal prices from auction software"
          color="#1a7a4a"
          onUpload={uploadSoldList}
          loading={soldLoading}
          result={soldResult}
        />
      </div>

      <Card>
        <h3 style={{ marginBottom:6, fontSize:15 }}>📌 Expected Excel Columns</h3>
        <p style={{ color:'#888', fontSize:12, marginBottom:12 }}>The system auto-detects these column names (case-insensitive, spaces/underscores flexible):</p>
        <div style={{ display:'flex', gap:24, flexWrap:'wrap' }}>
          <div>
            <div style={{ fontWeight:700, fontSize:12, color:'#1a3c5e', marginBottom:6 }}>CATALOGUE</div>
            {['Garden','Grade','Mark','Sale No','Invoice No','Bags','Net Wt','Broker','Upset Price','Last Sale Price','Date'].map(c => (
              <div key={c} style={{ fontSize:12, padding:'2px 0', color:'#555' }}>• {c}</div>
            ))}
          </div>
          <div>
            <div style={{ fontWeight:700, fontSize:12, color:'#1a7a4a', marginBottom:6 }}>SOLD LIST</div>
            {['Garden','Grade','Mark','Sale No','Invoice No','Bags','Net Wt','Broker','Deal Price','Buyer Code','Date'].map(c => (
              <div key={c} style={{ fontSize:12, padding:'2px 0', color:'#555' }}>• {c}</div>
            ))}
          </div>
        </div>
      </Card>

      <Card>
        <h3 style={{ marginBottom:12, fontSize:15 }}>Import History</h3>
        <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
          <thead>
            <tr style={{ background:'#f0f4f8' }}>
              {['Type','File','Sale No','Imported','Skipped','Date'].map(h => (
                <th key={h} style={{ padding:'7px 10px', textAlign:'left', fontWeight:600, borderBottom:'2px solid #e2e8f0' }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {logs.map((l, i) => (
              <tr key={i} style={{ borderBottom:'1px solid #f0f4f8' }}>
                <td style={{ padding:'7px 10px' }}>
                  <span style={{ background: l.file_type==='catalogue'?'#dbeafe':'#dcfce7', color: l.file_type==='catalogue'?'#1e40af':'#166534', padding:'2px 8px', borderRadius:99, fontSize:11, fontWeight:600 }}>
                    {l.file_type}
                  </span>
                </td>
                <td style={{ padding:'7px 10px', fontSize:12 }}>{l.filename}</td>
                <td style={{ padding:'7px 10px' }}>{l.sale_no || '—'}</td>
                <td style={{ padding:'7px 10px', color:'#1a7a4a', fontWeight:700 }}>{l.rows_imported}</td>
                <td style={{ padding:'7px 10px', color: l.rows_skipped>0?'#c0392b':'#888' }}>{l.rows_skipped}</td>
                <td style={{ padding:'7px 10px', color:'#888' }}>{new Date(l.imported_at).toLocaleString('en-IN')}</td>
              </tr>
            ))}
            {logs.length === 0 && (
              <tr><td colSpan={6} style={{ padding:20, textAlign:'center', color:'#aaa' }}>No imports yet</td></tr>
            )}
          </tbody>
        </table>
      </Card>
    </div>
  );
}
